Cc: Junjie Cao <junjie.cao@linux.dev>
Signed-off-by: Ryusuke Konishi <konishi.ryusuke@gmail.com>
Signed-off-by: Viacheslav Dubeyko <slava@dubeyko.com>

Here is the root cause:
The ioctl handler `nilfs_ioctl_mark_blocks_dirty()` does not validate that `bd_oblocknr` is non-zero before using it to detect dead blocks. Block 0 is always invalid for garbage collection (it stores the primary superblock). When a corrupted request sets `bd_oblocknr` to 0, and the subsequent `nilfs_bmap_lookup_at_level()` returns `-ENOENT` (setting `bd_blocknr` to 0), the dead‑block check (`bd_oblocknr != bd_blocknr`) incorrectly evaluates to false (both are 0). This bypasses the skip logic and causes `nilfs_bmap_mark()` to be called on a non‑existent block, eventually triggering `WARN_ON(ret == -ENOENT)` in `nilfs_btree_do_lookup()`.

Here is the patch:
  */
 static int nilfs_ioctl_mark_blocks_dirty(struct the_nilfs *nilfs,
 					 struct nilfs_argv *argv, void *buf)
 {
 	size_t nmembs = argv->v_nmembs;
 	struct nilfs_bmap *bmap = NILFS_I(nilfs->ns_dat)->i_bmap;
 	struct nilfs_bdesc *bdescs = buf;
 	struct buffer_head *bh;
 	int ret, i;

 	for (i = 0; i < nmembs; i++) {
+		/*
+		 * bd_oblocknr must never be 0 as block 0
+		 * is never a valid GC target block
+		 */
+		if (unlikely(!bdescs[i].bd_oblocknr))
+			return -EINVAL;
 		/* XXX: use macro or inline func to check liveness */
 		ret = nilfs_bmap_lookup_at_level(bmap,
 						 bdescs[i].bd_offset,
 						 bdescs[i].bd_level + 1,
 						 &bdescs[i].bd_blocknr);
 		if (ret < 0) {
 			if (ret != -ENOENT)
 				return ret;
 			bdescs[i].bd_blocknr = 0;
 		}
 		if (bdescs[i].bd_blocknr != bdescs[i].bd_oblocknr)
 			/* skip dead block */
 			continue;
 		if (bdescs[i].bd_level == 0) {
 			ret = nilfs_mdt_get_block(nilfs->ns_dat,
 						  bdescs[i].bd_offset,
 						  false, NULL, &bh);
 			if (unlikely(ret)) {
 				WARN_ON(ret == -ENOENT);
 				return ret;
 			}
 			mark_buffer_dirty(bh);
 			nilfs_mdt_mark_dirty(nilfs->ns_dat);
 			put_bh(bh);
 		} else {
 			ret = nilfs_bmap_mark(bmap, bdescs[i].bd_offset,
 					      bdescs[i].bd_level);
 			if (ret < 0) {
 				WARN_ON(ret == -ENOENT);
 				return ret;
 			}
 		}
 	}
 	return nmembs;
 }



